/**
 * Genera una seta/champiñón estilizado en voxels CENTRADA EXACTAMENTE en el punto objetivo.
 *
 * @param {number} originX - Coordenada X del centro exacto del tallo.
 * @param {number} originY - Coordenada Y del suelo de la seta.
 * @param {number} originZ - Coordenada Z del centro exacto del tallo.
 * @param {Object} [options] - Parámetros de personalización.
 * @param {number} [options.capRadius=8] - Radio máximo del sombrero.
 * @param {number} [options.capHeight=7] - Altura del sombrero.
 * @param {number} [options.stemRadius=3] - Radio medio del pie/tallo.
 * @param {number} [options.stemHeight=9] - Altura del pie/tallo.
 * @param {boolean} [options.addSpots=true] - Si añade motas blancas en el sombrero.
 * @param {string|number} [options.stemMat='adoquin'] - Material del tallo.
 * @param {string|number} [options.capMat='red_concrete'] - Material del sombrero.
 * @param {string|number} [options.spotMat='yellow_concrete'] - Material de las motas.
 */
function buildMushroom(originX, originY, originZ, options) {
    options = options || {};
    const capRadius = options.capRadius || 8;
    const capHeight = options.capHeight || 7;
    const stemRadius = options.stemRadius || 3;
    const stemHeight = options.stemHeight || 9;
    const addSpots = options.addSpots !== undefined ? options.addSpots : true;

    const stemMat = options.stemMat || 'adoquin';
    const capMat = options.capMat || 'red_concrete';
    const spotMat = options.spotMat || 'yellow_concrete';

    if (typeof beginBatch === 'function') beginBatch();

    // 1. TALLO / PIE CENTRADO EN (originX, originZ)
    for (let y = 0; y < stemHeight; y++) {
        const currentStemRadius = y < 2 ? stemRadius + 1 : stemRadius;
        const currentStemRadSq = currentStemRadius * currentStemRadius;

        for (let dx = -capRadius; dx <= capRadius; dx++) {
            for (let dz = -capRadius; dz <= capRadius; dz++) {
                const distSq = dx * dx + dz * dz;
                if (distSq <= currentStemRadSq) {
                    setVoxel(originX + dx, originY + y, originZ + dz, stemMat);
                }
            }
        }
    }

    // 2. SOMBRERO CENTRADO EN (originX, originZ)
    const capStartY = stemHeight - 1;

    for (let cy = 0; cy < capHeight; cy++) {
        const progress = cy / capHeight;
        const layerRadius = capRadius * Math.sqrt(1 - progress * 0.85);
        const layerRadSq = layerRadius * layerRadius;
        const currentY = capStartY + cy;

        for (let dx = -capRadius; dx <= capRadius; dx++) {
            for (let dz = -capRadius; dz <= capRadius; dz++) {
                const distSq = dx * dx + dz * dz;

                if (distSq <= layerRadSq) {
                    const isOuterShell = distSq >= (layerRadius - 1.5) * (layerRadius - 1.5);
                    const isTopCap = cy >= capHeight - 2;
                    let mat = capMat;

                    if (addSpots && (isOuterShell || isTopCap)) {
                        const spotPattern = Math.abs(Math.sin((originX + dx) * 12.9898 + currentY * 78.233 + (originZ + dz) * 37.719)) * 43758.5453;
                        const isSpot = (spotPattern - Math.floor(spotPattern)) > 0.82;
                        if (isSpot) mat = spotMat;
                    }

                    setVoxel(originX + dx, originY + currentY, originZ + dz, mat);
                }
            }
        }
    }

    if (typeof endBatch === 'function') endBatch();
    if (typeof toast === 'function') toast('🍄 ¡Seta Gigante construida en [' + originX + ',' + originY + ',' + originZ + ']!');
    console.log('[SETA GIGANTE] Construida centrada en [' + originX + ',' + originY + ',' + originZ + ']');
}

function getMushroomTarget() {
    if (typeof mcRaycast === 'function') {
        var hit = mcRaycast(30, true);
        if (hit && hit.cell) {
            var nx = hit.normal ? hit.normal[0] : 0;
            var ny = hit.normal ? hit.normal[1] : 0;
            var nz = hit.normal ? hit.normal[2] : 0;
            return {
                x: hit.cell[0] + nx,
                y: hit.cell[1] + (ny > 0 ? 1 : 0),
                z: hit.cell[2] + nz
            };
        }
    }
    if (typeof mc !== 'undefined' && mc.pos) {
        return {
            x: Math.floor(Array.isArray(mc.pos) ? mc.pos[0] : mc.pos.x),
            y: Math.floor(Array.isArray(mc.pos) ? mc.pos[1] : mc.pos.y),
            z: Math.floor(Array.isArray(mc.pos) ? mc.pos[2] : mc.pos.z)
        };
    }
    return { x: 50, y: 15, z: 50 };
}

